using System;
using System.Collections.Generic;
using System.Linq;
using Astra.Core.Infrastructure;
using Astra.Core.Models;
using Astra.Core.Services;
using Microsoft.Win32;

namespace Astra.Toolbox
{
    public static class SupplementalCatalog
    {
        private static readonly IReadOnlyList<TweakDefinition> definitions = Create();
        public static IReadOnlyList<TweakDefinition> All { get { return definitions; } }

        private static IReadOnlyList<TweakDefinition> Create()
        {
            var list = new List<TweakDefinition>();
            list.Add(Define("exm-restart-sign-on-off", "Require manual sign-in after restart", "Disables automatic restart sign-on (ARSO); Windows will not sign in automatically to finish setup after a restart.", "Security", RegistryHive.LocalMachine, @"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System", "DisableAutomaticRestartSignOn", 1, true, TweakRisk.Medium, "Setup waits for manual sign-in after restarting. This does not disable Windows updates."));
            list.Add(Define("exm-notification-sound-off", "Silent notification sounds", "Disables global notification audio without disabling notification banners.", "QoL", RegistryHive.CurrentUser, @"SOFTWARE\Microsoft\Windows\CurrentVersion\Notifications\Settings", "NOC_GLOBAL_SETTING_ALLOW_NOTIFICATION_SOUND", 0, false, TweakRisk.Low, "You may miss audible alerts. Notification banners remain available."));
            list.Add(Define("exm-chrome-online-spelling-off", "Disable Chrome online spell checking", "Prevents Chrome's online spell-check service from sending text for spelling suggestions; local spell checking is retained.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "SpellCheckServiceEnabled", 0, true, TweakRisk.Low, "Restart Chrome to refresh policy. Local spell checking remains available; online enhanced suggestions are disabled."));
            list.Add(Define("exm-chrome-geolocation-off", "Block Chrome website geolocation", "Sets Chrome's default geolocation policy to block websites from requesting device location.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultGeolocationSetting", 2, true, TweakRisk.Medium, "Location-dependent websites may stop working correctly. Restart Chrome to refresh policy."));
            const string windowsPolicy = "Windows Pro, Enterprise, Education or IoT policy; Windows Home may ignore it. Existing organization policy can override the setting.";
            const string chromePolicy = "Chrome policy only. Chrome may show managed settings. Check chrome://policy to confirm acceptance; a matching registry value alone is not proof.";
            list.Add(Define("sys-first-signin-animation-off", "Skip the first-sign-in animation", "Skips the animation shown when a new Windows account signs in for the first time; ordinary sign-ins are unchanged.", "Startup", RegistryHive.LocalMachine, @"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System", "EnableFirstLogonAnimation", 0, true, TweakRisk.Low, "Applies to a new account's first sign-in. Also suppresses Microsoft-account service opt-in prompts. No ongoing FPS or ordinary login benefit is promised.", false, windowsPolicy));
            list.Add(Define("sys-signin-account-details-off", "Hide additional account details at sign-in", "Prevents enabling additional account details on the Windows sign-in screen.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\System", "BlockUserFromShowingAccountDetailsOnSignin", 1, true, TweakRisk.Low, "Takes effect when the sign-in screen is next shown. This is not a guarantee that all user identification disappears.", false, windowsPolicy));
            list.Add(Define("sys-start-recent-apps-off", "Hide recently installed apps in Start", "Hides the Recently added list while keeping installed applications accessible.", "QoL", RegistryHive.CurrentUser, @"SOFTWARE\Policies\Microsoft\Windows\Explorer", "HideRecentlyAddedApps", 1, false, TweakRisk.Low, "Restart Windows to refresh Start. The related Settings toggle is locked while this policy is set; applications are not removed.", true, windowsPolicy));
            list.Add(Define("sys-app-account-info-off", "Deny Windows-app account-information access", "Sets the default Windows-app privacy policy to deny account-information access.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessAccountInfo", 2, true, TweakRisk.Medium, "Restart affected apps. Identity or personalization features can stop working. Per-app policy exceptions take precedence; arbitrary desktop programs are not universally covered.", false, windowsPolicy));
            list.Add(Define("sys-app-contacts-off", "Deny Windows-app contacts access", "Sets the default Windows-app privacy policy to deny contacts access without deleting contacts.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessContacts", 2, true, TweakRisk.Medium, "Restart affected apps. Contact-dependent features can stop working. Per-app exceptions take precedence; arbitrary desktop programs are not universally covered.", false, windowsPolicy));
            list.Add(Define("chrome-search-suggestions-off", "Disable Chrome online search suggestions", "Stops Chrome's default search provider from supplying online search suggestions in the address bar.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "SearchSuggestEnabled", 0, true, TweakRisk.Low, "Local bookmark and browsing-history suggestions remain. Refresh Chrome policy or restart the browser; this does not change Windows Start search.", false, chromePolicy));
            list.Add(Define("chrome-network-prediction-off", "Disable Chrome speculative connections", "Disables Chrome DNS prefetch, preconnection and prerender prediction.", "Network", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "NetworkPredictionOptions", 2, true, TweakRisk.Medium, "Refresh Chrome policy or restart the browser. Websites may load more slowly. This is a privacy/network preference, not an FPS optimization.", false, chromePolicy));
            list.Add(Define("chrome-third-party-cookies-off", "Block Chrome third-party cookies", "Blocks third-party cookies by default in Chrome.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "BlockThirdPartyCookies", 1, true, TweakRisk.Medium, "Refresh Chrome policy or restart the browser. Embedded authentication and content can break. Site exceptions and Incognito behavior require separate review.", false, chromePolicy));
            list.Add(Define("chrome-website-notifications-off", "Block Chrome website notifications by default", "Sets Chrome's default website-notification permission to blocked.", "QoL", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultNotificationsSetting", 2, true, TweakRisk.Medium, "Refresh Chrome policy or restart the browser. Website alerts may be unavailable; permission exceptions can still matter. Windows notifications are not disabled.", false, chromePolicy));
            list.Add(Define("chrome-translation-off", "Disable Chrome built-in translation", "Disables Chrome's built-in translation feature.", "Apps", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "TranslateEnabled", 0, true, TweakRisk.Medium, "Refresh Chrome policy or restart the browser. Translation is removed from both the toolbar and context menu, not just automatic prompts.", false, chromePolicy));
            list.Add(Define("chrome-download-location-prompt", "Ask where to save Chrome downloads", "Shows a save-location dialog for Chrome downloads.", "QoL", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "PromptForDownloadLocation", 1, true, TweakRisk.Low, "Refresh Chrome policy or restart the browser. Each download requires a location choice. Download security checks remain unchanged.", false, chromePolicy));
            list.Add(Define("chrome-cast-off", "Disable Google Cast in Chrome", "Disables Chrome's media router and Google Cast integration.", "Apps", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "EnableMediaRouter", 0, true, TweakRisk.Medium, "Restart Chrome; this policy does not refresh dynamically. Casting becomes unavailable. No measurable gaming gain is promised.", false, chromePolicy));
            list.Add(Define("chrome-memory-saver-on", "Enable Chrome Memory Saver", "Enables discarding eligible inactive Chrome tabs to reclaim memory.", "Memory", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "HighEfficiencyModeEnabled", 1, true, TweakRisk.Medium, "Chrome 108 or newer. Refresh Chrome policy or restart the browser. Returning tabs can reload; exclude critical web applications where supported. Not a blanket FPS increase.", false, chromePolicy));
            list.Add(Define("chrome-low-battery-saver-on", "Enable Chrome Energy Saver at low battery", "Enables Chrome's lower-power mode when running on battery with a low charge.", "Power", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "BatterySaverModeAvailability", 1, true, TweakRisk.Medium, "Chrome 108 or newer. Refresh Chrome policy or restart the browser. Chrome frame rate is throttled to reduce power consumption; this is not a desktop-performance boost.", false, chromePolicy));
            list.Add(Define("exm-settings-online-tips-off", "Disable online tips in Windows Settings", "Prevents Settings from retrieving online tips and help content; local Settings controls remain available.", "QoL", RegistryHive.LocalMachine, @"SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer", "AllowOnlineTips", 0, true, TweakRisk.Low, "Online Settings help is reduced. Reopen Settings; this is not the same as disabling promotional tips or a performance improvement.", false, windowsPolicy + " EXM 0.95 line 1577; Microsoft Settings/AllowOnlineTips policy."));
            list.Add(Define("exm-store-push-install-off", "Block remote Microsoft Store app installation", "Prevents pushing Store applications to this PC from another device or the web.", "Apps", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\PushToInstall", "DisablePushToInstall", 1, true, TweakRisk.Low, "Remote app installation becomes unavailable. Local Store installation and updates are not disabled by this setting; no service is changed.", false, windowsPolicy + " EXM 0.95 line 1578; Microsoft PushToInstall ADMX policy."));
            list.Add(Define("exm-message-cloud-sync-off", "Disable cellular-message cloud backup", "Disallows cloud backup and restoration of cellular text messages through the applicable Windows feature.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\Messaging", "AllowMessageSync", 0, true, TweakRisk.Low, "Only relevant when cellular-message cloud backup is available. This is not a general Phone Link, email or app-messaging restriction.", false, windowsPolicy + " EXM 0.95 line 1233; Microsoft Messaging/AllowMessageSync policy."));
            list.Add(Define("exm-chrome-feedback-off", "Hide Chrome's Report an Issue command", "Disables Chrome's user-initiated feedback command and its keyboard shortcut.", "Apps", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "UserFeedbackAllowed", 0, true, TweakRisk.Low, "Chrome 77 or newer. Sending issue reports through this command is unavailable. This does not disable all browser metrics or improve gaming performance.", false, chromePolicy + " EXM 0.95 line 2603; Chromium UserFeedbackAllowed policy."));
            list.Add(Define("exm-chrome-spellchecking-off", "Disable all Chrome spellchecking", "Disables Chrome spellchecking, including local dictionaries, rather than only the online spelling service.", "Apps", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "SpellcheckEnabled", 0, true, TweakRisk.Medium, "Chrome 65 or newer. Local spelling suggestions and related accessibility assistance are lost. Choose the online-only spelling option instead if local checking is wanted.", false, chromePolicy + " EXM 0.95 line 2605; Chromium SpellcheckEnabled policy."));
            list.Add(Define("exm-chrome-sensors-off", "Block Chrome website sensor access", "Sets Chrome's default permission for website sensor access to blocked.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultSensorsSetting", 2, true, TweakRisk.Medium, "Chrome 88 or newer. Sensor-dependent websites can fail; applicable site-policy exceptions may take precedence. Windows hardware sensors remain enabled.", false, chromePolicy + " EXM 0.95 line 2615; Chromium DefaultSensorsSetting policy."));
            list.Add(Define("exm-chrome-serial-off", "Block Chrome Web Serial requests", "Prevents websites from requesting Web Serial access by default.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultSerialGuardSetting", 2, true, TweakRisk.Medium, "Chrome 86 or newer. Browser serial-device tools can stop working; applicable policy exceptions may take precedence. Ordinary Windows COM-port use is unaffected.", false, chromePolicy + " EXM 0.95 line 2616; Chromium DefaultSerialGuardSetting policy."));
            list.Add(Define("exm-chrome-bluetooth-off", "Block Chrome Web Bluetooth requests", "Prevents websites from requesting Web Bluetooth access by default.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultWebBluetoothGuardSetting", 2, true, TweakRisk.Medium, "Chrome 50 or newer. Browser Bluetooth-device workflows can fail; applicable policy exceptions may take precedence. Windows Bluetooth and headsets remain available.", false, chromePolicy + " EXM 0.95 line 2617; Chromium DefaultWebBluetoothGuardSetting policy."));
            list.Add(Define("exm-chrome-webusb-off", "Block Chrome WebUSB requests", "Prevents websites from requesting WebUSB access by default.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Google\Chrome", "DefaultWebUsbGuardSetting", 2, true, TweakRisk.Medium, "Chrome 67 or newer. Browser USB-device workflows can fail; applicable policy exceptions may take precedence. Normal Windows USB operation is unaffected.", false, chromePolicy + " EXM 0.95 line 2618; Chromium DefaultWebUsbGuardSetting policy."));
            const string appPrivacyPolicy = windowsPolicy + " Documented AppPrivacy default, not a direct ConsentStore edit. Per-app policy exceptions take precedence; arbitrary desktop programs are not universally covered. The corresponding user choice is locked while configured.";
            list.Add(Define("exm-app-diagnostics-off", "Deny Windows-app access to other-app diagnostics", "Denies Windows-app access to diagnostic information about other applications, which can include user identity.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsGetDiagnosticInfo", 2, true, TweakRisk.Medium, "Restart affected apps. Diagnostic integrations can fail. This does not disable Windows telemetry, error reporting or system diagnostic services.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 lines 1215, 1316 and 1897."));
            list.Add(Define("exm-app-calendar-off", "Deny Windows-app calendar access", "Denies calendar-data access by default for applicable Windows applications without deleting calendar data.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessCalendar", 2, true, TweakRisk.Medium, "Restart affected apps. Calendar integration and appointment-related features can fail.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 lines 1216 and 1317."));
            list.Add(Define("exm-app-email-off", "Deny Windows-app email access", "Denies email-data access by default for applicable Windows applications without deleting mail.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessEmail", 2, true, TweakRisk.Medium, "Restart affected apps. Mail-dependent application features can fail; this is not a blanket block on desktop email clients.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 line 1217."));
            list.Add(Define("exm-app-messaging-off", "Deny Windows-app text-message access", "Denies reading or sending text and MMS messages through applicable Windows-app permissions.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessMessaging", 2, true, TweakRisk.Medium, "Restart affected apps. Text-message integrations can fail. This is distinct from cellular-message cloud backup and does not universally restrict desktop messaging clients.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 lines 1231 and 1320."));
            list.Add(Define("exm-app-phone-off", "Deny Windows-app phone-call access", "Denies phone-call access by default for applicable Windows applications.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessPhone", 2, true, TweakRisk.Medium, "Restart affected apps. Calling integrations can fail; this does not disable phone hardware or every desktop calling application.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 lines 1218 and 1326."));
            list.Add(Define("exm-app-call-history-off", "Deny Windows-app call-history access", "Denies call-history access by default for applicable Windows applications without deleting existing history.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessCallHistory", 2, true, TweakRisk.Medium, "Restart affected apps. Call-history-dependent integrations can fail; history is not erased.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 line 1327."));
            list.Add(Define("exm-app-tasks-off", "Deny Windows-app task-data access", "Denies task-data access by default for applicable Windows applications without deleting task lists.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessTasks", 2, true, TweakRisk.Medium, "Restart affected apps. Task-list integration can fail; Windows scheduled tasks are not disabled.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 line 1219."));
            list.Add(Define("exm-app-radio-control-off", "Deny Windows-app control of radios", "Denies applicable Windows applications permission to control radios.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessRadios", 2, true, TweakRisk.Medium, "Restart affected apps. Application radio-control features can fail; Wi-Fi and Bluetooth drivers are not switched off.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 line 1329."));
            list.Add(Define("exm-app-notification-reading-off", "Deny Windows-app notification-reading access", "Restricts applicable Windows applications from accessing notifications through their notification-listener permission.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessNotifications", 2, true, TweakRisk.Medium, "Restart affected apps. Notification-reading integrations can fail. Notification banners, sounds and ordinary app alerts are not disabled by this setting.", false, appPrivacyPolicy + " Corrected equivalent of EXM 0.95 lines 1330 and 1939."));
            list.Add(Define("exm-app-unpaired-device-sync-off", "Deny Windows-app unpaired-device communication", "Restricts applicable Windows applications from communicating with unpaired wireless devices.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsSyncWithDevices", 2, true, TweakRisk.Medium, "Restart affected apps. Unpaired-device integrations can fail; this is not a general Bluetooth disable switch or a trusted-devices policy.", false, appPrivacyPolicy + " Corrected permission intention from EXM 0.95 line 1318."));
            list.Add(Define("sys-app-motion-off", "Deny Windows-app motion-data access", "Denies motion-data access by default for applicable Windows applications.", "Privacy", RegistryHive.LocalMachine, @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy", "LetAppsAccessMotion", 2, true, TweakRisk.Medium, "Restart affected apps. Motion-dependent applications can fail. This is not Windows Activity History suppression.", false, appPrivacyPolicy + " Additional documented permission choice; EXM line 1315's activity entry is not a verified equivalent."));
            var ids = new HashSet<string>(TweakCatalog.All.Select(delegate(TweakDefinition d) { return d.Id; }), StringComparer.Ordinal);
            var targets = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var definition in TweakCatalog.All)
                if (definition.RegistryTargets != null)
                    foreach (var target in definition.RegistryTargets) targets.Add(TargetIdentity(target));
            foreach (var definition in list)
            {
                if (!ids.Add(definition.Id)) throw new InvalidOperationException("Duplicate supplemental ID: " + definition.Id);
                foreach (var target in definition.RegistryTargets)
                    if (!targets.Add(TargetIdentity(target))) throw new InvalidOperationException("Supplemental registry target already exists: " + definition.Id);
            }
            return list.AsReadOnly();
        }

        private static string TargetIdentity(RegistryTarget target)
        {
            return target.Hive + "\\" + target.KeyPath + "\\" + target.ValueName;
        }

        private static TweakDefinition Define(string id, string title, string description, string category, RegistryHive hive, string key, string value, int desired, bool admin, TweakRisk risk, string caveat, bool restart = false, string note = null)
        {
            return new TweakDefinition
            {
                Id = id,
                Title = title,
                Description = description,
                Category = category,
                Kind = TweakKind.Registry,
                Risk = risk,
                RequiresAdministrator = admin,
                RequiresRestart = restart,
                Recommended = risk == TweakRisk.Low,
                SecurityTradeOff = false,
                PerformanceUnproven = false,
                Caveat = caveat,
                Note = note,
                VendorTags = new string[0],
                RegistryTargets = new RegistryTarget[] { new RegistryTarget(hive, key, value, RegistryValueKind.DWord, desired, false) }
            };
        }

        public static TweakStatus ReadStatus(TweakDefinition definition, TweakEngine engine)
        {
            bool applied = definition.RegistryTargets.All(delegate(RegistryTarget target)
            {
                var current = RegistryHelper.Read(target.Hive, target.KeyPath, target.ValueName);
                return current == null ? target.MissingCountsAsApplied : RegistryHelper.Matches(current, target.ValueKind, target.DesiredValue);
            });
            return new TweakStatus(definition, applied, engine.HasBackup(definition.Id));
        }
    }
}
